CREATE OR REPLACE FUNCTION public.set_company_context_on_insert() RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS  DECLARE my_company_id UUID; BEGIN IF auth.uid() IS NULL THEN RETURN NEW; END IF; SELECT company_id INTO my_company_id FROM public.profiles WHERE id = auth.uid() LIMIT 1; NEW.company_id := COALESCE(my_company_id, NEW.company_id); IF TG_TABLE_NAME IN ('products', 'orders', 'suppliers') THEN IF NEW.user_id IS NULL THEN NEW.user_id := auth.uid(); END IF; END IF; RETURN NEW; END; ; 
